CREATE OR REPLACE FUNCTION public.guard_trip_source_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare b jsonb;begin
 if current_user<>'otr_trip_source_writer' or session_user<>'otr_trip_source_command_gateway' or tg_op not in ('INSERT','UPDATE') then raise exception 'TRIP_SOURCE_COMMANDS_DISABLED' using errcode='42501';end if;
 perform public.trip_source_pdf_registration_gate();
 if tg_level='STATEMENT' then return null;end if;
 if tg_op='INSERT' and public.trip_source_pdf_upload_v4_initial(tg_table_name,to_jsonb(new)) then return new;end if;
 if tg_table_name<>'trip_source_representations' then raise exception 'PDF_MUTATION_DENIED';end if;
 if new.source_id is distinct from (public.trip_source_pdf_upload_v4_scope()->>'source_id')::uuid then raise exception 'PDF_V4_SCOPE_DENIED';end if;
 if tg_op='UPDATE' then
  if old.role<>'ORIGINAL' or old.material_kind<>'BINARY' or old.mime_type<>'application/pdf' or old.remote_state<>'PENDING' or new.remote_state<>'VERIFIED' or new.row_revision<>old.row_revision+1 or new.verified_at is null or (to_jsonb(old)-array['row_revision','remote_state','verified_at']) is distinct from (to_jsonb(new)-array['row_revision','remote_state','verified_at']) or not exists(select 1 from public.trip_source_operations o join public.trip_sources s on s.id=o.source_id where o.representation_id=old.id and o.source_id=old.source_id and o.command='VERIFY_REPRESENTATION' and o.phase='IO_QUIESCENT' and o.worker_identity=session_user and o.expected_representation_row_revision=old.row_revision and o.bound_payload_sha256=old.payload_sha256 and o.bound_byte_count=old.byte_count and o.expected_source_row_revision=s.row_revision and o.material_revision=s.current_material_revision and o.actor_account_id=s.acquired_by) then raise exception 'PDF_MUTATION_DENIED';end if;
 else
  select body into b from public.trip_source_pdf_registrations where derived_representation_id=new.id and source_id=new.source_id;
  if b is null or new.role<>'DERIVED' or new.material_kind<>'TEXT' or new.row_revision<>1 or new.introduced_revision<>(b->'request'->>'sourceRevision')::bigint or new.parent_ids<>array[(b->'request'->>'originalRepresentationId')::uuid] or new.payload_sha256<>b->>'textSha256' or new.byte_count<>(b->>'textByteCount')::bigint or (case when b->'derivativeVersion'='2'::jsonb then new.transform_key<>'otr.pdf.qpdf-poppler' or new.transform_version<>'2' or b->>'profileSha256'<>'ca5a7b63bda8ed5c5b9018b82fbbd14c1a01f054a37b1c2ed76445152b36539c' or b->>'producer'<>'otr-source-pdf-qpdf-poppler/2' else new.transform_key<>'otr.pdf.literal-text' or new.transform_version<>'1' end) or new.transform_options_sha256<>b->>'transformOptionsSha256' or new.regenerability<>'POSSIBLE' then raise exception 'PDF_MUTATION_DENIED';end if;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION public.trip_source_assert_gate()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$begin
 if current_user<>'otr_trip_source_writer' or session_user<>'otr_trip_source_command_gateway' then raise exception 'SOURCE_ACCESS_DENIED' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'UNSUPPORTED_TRANSACTION_ISOLATION' using errcode='25000';end if;
 perform public.trip_source_pdf_upload_v4_scope();
end$function$

CREATE OR REPLACE FUNCTION public.trip_source_operation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$ declare mutable text[]:=array['phase','attempt_generation','attempt_id','worker_identity','admitted_at','io_finished_at','outcome','error_code','completed_at','result_source_row_revision','result_material_revision','result_representation_row_revision','result_remote_state','result_retention_state','result_action_id','result_verified_at','result_sha256'];
begin
 if current_user<>'otr_trip_source_writer' or session_user<>'otr_trip_source_command_gateway' or tg_op in ('DELETE','TRUNCATE') then
  raise exception 'TRIP_SOURCE_COMMANDS_DISABLED' using errcode='42501'; end if;
 perform public.trip_source_assert_gate();
 if tg_level='STATEMENT' then return null; end if;
 perform public.trip_source_pdf_upload_v4_operation(new);
 if tg_op='INSERT' then
  if new.phase not in ('ADMITTED','FINAL') or new.attempt_generation<>1 or new.attempt_id is not null or new.io_finished_at is not null then
   raise exception 'SOURCE_ATTEMPT_CONFLICT'; end if;
 elsif tg_op='UPDATE' then
  if old.phase='FINAL' or (to_jsonb(old)-mutable) is distinct from (to_jsonb(new)-mutable) then
   raise exception 'SOURCE_OPERATION_IMMUTABLE' using errcode='42501'; end if;
  if not (old.phase='ADMITTED' and new.phase in ('IO_ACTIVE','FINAL')
   or old.phase='IO_ACTIVE' and new.phase in ('IO_UNKNOWN','IO_QUIESCENT')
   or old.phase='IO_UNKNOWN' and new.phase='IO_QUIESCENT'
   or old.phase='IO_QUIESCENT' and new.phase in ('IO_ACTIVE','FINAL')
   or old.phase in ('IO_ACTIVE','IO_UNKNOWN') and new.phase='FINAL' and new.outcome='APPLIED' and new.result_remote_state='PENDING' and new.result_verified_at is null and new.result_action_id is null and (public.trip_source_pdf_beta_custody(old) or public.trip_source_pdf_reconciliation_custody_v1(old))) then raise exception 'SOURCE_PHASE_CONFLICT'; end if;
  if new.phase='IO_ACTIVE' then
   if new.attempt_generation<>old.attempt_generation+(case when old.phase='ADMITTED' then 0 else 1 end)
    or new.attempt_id is null or new.attempt_id is not distinct from old.attempt_id or new.worker_identity is distinct from session_user
    or new.admitted_at is null or new.io_finished_at is not null then raise exception 'SOURCE_ATTEMPT_CONFLICT'; end if;
  elsif new.attempt_generation<>old.attempt_generation or new.attempt_id is distinct from old.attempt_id
   or new.worker_identity is distinct from old.worker_identity or new.admitted_at is distinct from old.admitted_at then
   raise exception 'SOURCE_ATTEMPT_CONFLICT'; end if;
  if new.phase='FINAL' and new.io_finished_at is distinct from old.io_finished_at then raise exception 'SOURCE_ATTEMPT_CONFLICT'; end if;
 end if;
 if new.phase='FINAL' then
  if new.result_sha256 is distinct from public.trip_source_hash('otr-source-result-v1',public.trip_source_result_tuple(new)) then raise exception 'SOURCE_RESULT_INTEGRITY'; end if;
  if new.outcome<>'REJECTED' and (not exists(select 1 from public.trip_sources where id=new.source_id and trip_id=new.trip_id and acquired_by=new.actor_account_id)
   or not exists(select 1 from public.trip_source_representations r join public.trip_source_revisions v on v.source_id=r.source_id and v.material_revision=new.result_material_revision
    where r.id=new.representation_id and r.source_id=new.source_id and r.id=any(v.original_representation_ids))
   or new.result_action_id is not null and not exists(select 1 from public.trip_source_actions where id=new.result_action_id and source_id=new.source_id and actor_account_id=new.actor_account_id and operation_key=new.operation_key and operation_sha256=new.operation_sha256)) then raise exception 'SOURCE_RESULT_INTEGRITY'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.trip_source_pdf_upload_v4_command(q jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$declare a jsonb;begin
 a:=public.trip_source_pdf_upload_v4_scope();
 perform public.trip_source_pdf_upload_v4_source((q->>'actor_account_id')::uuid,(q->>'trip_id')::uuid,(q->>'source_id')::uuid);
 if q->>'command'='ACQUIRE_SOURCE' then
  if q is distinct from a then raise exception 'PDF_V4_ACQUISITION_CONFLICT';end if;
 elsif q->>'command' in ('PREPARE_REPRESENTATION','UPLOAD_ORIGINAL','VERIFY_REPRESENTATION') then
  if q->'payload'->>'representation_id' is distinct from a->'payload'->'original'->>'id' or
     q->'payload'->'material_revision' is distinct from '1'::jsonb then raise exception 'PDF_V4_ORIGINAL_CONFLICT';end if;
 else raise exception 'PDF_V4_COMMAND_DENIED';end if;
end$function$
